  INSERT INTO ai_knowledge_items (id, business_id, title, content, category, priority, is_active, metadata, created_at) VALUES (gen_random_uuid(), b_id, 'Product Range', 'Carries hardwood, engineered flooring, laminate, luxury vinyl plank, ceramic tile, and broadloom carpet from leading brands.', 'products', 9, true, '{}'::jsonb, now());
  INSERT INTO ai_knowledge_items (id, business_id, title, content, category, priority, is_active, metadata, created_at) VALUES (gen_random_uuid(), b_id, 'Installation Services', 'Professional installation available for all flooring types, including subfloor preparation, old floor removal, and finishing trim.', 'services', 8, true, '{}'::jsonb, now());
  INSERT INTO ai_knowledge_items (id, business_id, title, content, category, priority, is_active, metadata, created_at) VALUES (gen_random_uuid(), b_id, 'Free Estimates', 'Free in-home measurements and written estimates. Bring room dimensions in-store for a quick ballpark quote.', 'policies', 7, true, '{}'::jsonb, now());
  INSERT INTO ai_knowledge_items (id, business_id, title, content, category, priority, is_active, metadata, created_at) VALUES (gen_random_uuid(), b_id, 'Warranty', 'Manufacturer warranties range from 10 years to lifetime depending on product. Installation workmanship is guaranteed for two years.', 'policies', 6, true, '{}'::jsonb, now());
