  INSERT INTO business_photos (id, business_id, url, alt_text, sort_order, is_cover, created_at) VALUES (gen_random_uuid(), b_id, 'https://images.unsplash.com/photo-1513694203232-719a280e022f?w=800', 'Cozy interior featuring new laminate flooring', 1, false, now());
  INSERT INTO business_photos (id, business_id, url, alt_text, sort_order, is_cover, created_at) VALUES (gen_random_uuid(), b_id, 'https://images.unsplash.com/photo-1503387762-592deb58ef4e?w=800', 'Modern home interior with fresh vinyl plank floors', 2, false, now());
